import functools
import inspect
import sys

if sys.version_info >= (3, 13):  # pragma: no cover
    from inspect import iscoroutinefunction
else:  # pragma: no cover
    from asyncio import iscoroutinefunction

def is_async_callable(obj: Any) -> bool:
    while True:
        if iscoroutinefunction(obj) or (callable(obj) and iscoroutinefunction(getattr(obj, "__call__", None))):
            return True
        unwrapped = inspect.unwrap(obj)
        if unwrapped is not obj:
            obj = unwrapped
            continue
        if isinstance(obj, functools.partial):
            obj = obj.func
            continue
        break
    return False

def is_gen_callable(obj: Any) -> bool:
    while True:
        if inspect.isgeneratorfunction(obj) or (callable(obj) and inspect.isgeneratorfunction(getattr(obj, "__call__", None))):
            return True
        unwrapped = inspect.unwrap(obj)
        if unwrapped is not obj:
            obj = unwrapped
            continue
        if isinstance(obj, functools.partial):
            obj = obj.func
            continue
        break
    return False

def is_async_gen_callable(obj: Any) -> bool:
    while True:
        if inspect.isasyncgenfunction(obj) or (callable(obj) and inspect.isasyncgenfunction(getattr(obj, "__call__", None))):
            return True
        unwrapped = inspect.unwrap(obj)
        if unwrapped is not obj:
            obj = unwrapped
            continue
        if isinstance(obj, functools.partial):
